<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Template\Domain;

use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\TemplateUidVO;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\TemplateCodeVO;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\Accessor\TemplateCodeAccessor;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\TemplateTenantVO;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\Accessor\TemplateTenantAccessor;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\TemplateThemeVO;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\Accessor\TemplateThemeAccessor;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\TemplateChannelVO;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\Accessor\TemplateChannelAccessor;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\TemplateEnabledVO;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\Accessor\TemplateEnabledAccessor;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\TemplateVersionVO;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\Accessor\TemplateVersionAccessor;
use Civi\Lughauth\Features\Document\Template\Domain\Formula\EnabledCalculator;
use Civi\Lughauth\Features\Document\Template\Domain\Event\TemplateCreateEvent;
use Civi\Lughauth\Features\Document\Template\Domain\Event\TemplateUpdateEvent;
use Civi\Lughauth\Features\Document\Template\Domain\Event\TemplateDeleteEvent;
use Civi\Lughauth\Features\Document\Template\Domain\Event\TemplateEnableEvent;
use Civi\Lughauth\Features\Document\Template\Domain\Event\TemplateDisableEvent;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Document\Theme\Domain\ThemeRef;

class Template extends TemplateRef
{
    use TemplateCodeAccessor;
    use TemplateTenantAccessor;
    use TemplateThemeAccessor;
    use TemplateChannelAccessor;
    use TemplateEnabledAccessor;
    use TemplateVersionAccessor;
    private array $recordedEvents = [];

    public function __construct(
        TemplateUidVO|string $uid,
        TemplateCodeVO|string $code,
        TemplateChannelVO|TemplateChannelOptions $channel,
        TemplateTenantVO|TenantRef|null $tenant = null,
        TemplateThemeVO|ThemeRef|null $theme = null,
        TemplateEnabledVO|bool|null $enabled = null,
        TemplateVersionVO|int|null $version = null,
    ) {
        parent::__construct($uid);
        $this->_code = TemplateCodeVO::from($code);
        $this->_tenant = null === $tenant ? TemplateTenantVO::empty() : TemplateTenantVO::from($tenant);
        $this->_theme = null === $theme ? TemplateThemeVO::empty() : TemplateThemeVO::from($theme);
        $this->_channel = TemplateChannelVO::from($channel);
        $this->_enabled = null === $enabled ? TemplateEnabledVO::empty() : TemplateEnabledVO::from($enabled);
        $this->_version = null === $version ? TemplateVersionVO::empty() : TemplateVersionVO::from($version);
    }
    public function replace(TemplateAttributes $values): Template
    {
        $value = clone $this;
        $value->_code = $values->getCodeOrCurrent($this->_code);
        $value->_tenant = $values->getTenantOrCurrent($this->_tenant);
        $value->_theme = $values->getThemeOrCurrent($this->_theme);
        $value->_channel = $values->getChannelOrCurrent($this->_channel);
        $value->_enabled = $values->getEnabledOrCurrent($this->_enabled);
        $value->_version = $values->getVersionOrCurrent($this->_version);
        return $value;
    }
    public static function calculatedFields(): array
    {
        return [ 'enabled'];
    }
    public static function create(TemplateAttributes $values): Template
    {
        $calculated = clone $values;
        $calculated->enabled(EnabledCalculator::calculateEnabled());
        $value = $calculated->createNewInstance();
        $value->recordedEvents[] = new TemplateCreateEvent($value);
        return $value;
    }
    public function update(TemplateAttributes $values): Template
    {
        $calculated = clone $values;
        $calculated->enabled(EnabledCalculator::calculateEnabled($this));
        $value = $this->replace($calculated);
        $value->recordedEvents[] = new TemplateUpdateEvent($value, $this);
        return $value;
    }
    public function delete(): Template
    {
        $value = clone $this;
        $value->recordedEvents[] = new TemplateDeleteEvent($value);
        return $value;
    }
    public function enable(): Template
    {
        $value = clone $this;
        $value->_enabled = TemplateEnabledVO::from(true);
        $value->recordedEvents[] = new TemplateEnableEvent($value, original: $this);
        return $value;
    }
    public function disable(): Template
    {
        $value = clone $this;
        $value->_enabled = TemplateEnabledVO::from(false);
        $value->recordedEvents[] = new TemplateDisableEvent($value, original: $this);
        return $value;
    }
    public function asPublicJson(): array
    {
        $data = [];
        $data['uid'] = $this->uid();
        $data['code'] = $this->getCode();
        $tenant = $this->getTenant();
        if (null !== $tenant) {
            $data['tenant'] = ['$ref' => $tenant->uid() ];
        }
        $theme = $this->getTheme();
        if (null !== $theme) {
            $data['theme'] = ['$ref' => $theme->uid() ];
        }
        $data['channel'] = $this->getChannel();
        $data['enabled'] = $this->isEnabled();
        $data['version'] = $this->getVersion();
        return $data;
    }
    public function toAttributes(): TemplateAttributes
    {
        return (new TemplateAttributes())
          ->uid($this->uid())
          ->code($this->_code)
          ->tenant($this->_tenant)
          ->theme($this->_theme)
          ->channel($this->_channel)
          ->enabled($this->_enabled)
          ->version($this->_version);
    }
    public function getTheEvents(): array
    {
        return [...$this->recordedEvents];
    }
}
